& {
  if (-not (Get-Command git -ErrorAction SilentlyContinue) -and -not (Test-Path "$env:ProgramFiles\Git\cmd\git.exe")) { winget install --id Git.Git -e --source winget }
  $bin = "$env:USERPROFILE\.local\bin"
  $p = [Environment]::GetEnvironmentVariable('Path', 'User')
  if (($p -split ';') -notcontains $bin) { [Environment]::SetEnvironmentVariable('Path', (("$p".TrimEnd(';'), $bin | Where-Object { $_ }) -join ';'), 'User') }
  if (($env:Path -split ';') -notcontains $bin) { $env:Path += ";$bin" }
  irm https://claude.ai/install.ps1 | iex
  claude --version
}

& {
  New-Item -ItemType Directory -Force "$env:USERPROFILE\.local\bin" | Out-Null
  $bin = "$env:USERPROFILE\.local\bin"
  $p = [Environment]::GetEnvironmentVariable('Path', 'User')
  if (($p -split ';') -notcontains $bin) { [Environment]::SetEnvironmentVariable('Path', (("$p".TrimEnd(';'), $bin | Where-Object { $_ }) -join ';'), 'User') }
  if (($env:Path -split ';') -notcontains $bin) { $env:Path += ";$bin" }
  Set-Content -Encoding ascii "$bin\cc.cmd" "@echo off`r`nclaude update`r`nclaude --dangerously-skip-permissions %*"
  'cc is ready: it updates Claude Code, then starts it without permission prompts'
}

& {
  New-Item -ItemType Directory -Force "$env:USERPROFILE\.local\bin" | Out-Null
  $bin = "$env:USERPROFILE\.local\bin"
  $p = [Environment]::GetEnvironmentVariable('Path', 'User')
  if (($p -split ';') -notcontains $bin) { [Environment]::SetEnvironmentVariable('Path', (("$p".TrimEnd(';'), $bin | Where-Object { $_ }) -join ';'), 'User') }
  if (($env:Path -split ';') -notcontains $bin) { $env:Path += ";$bin" }
  Set-Content -Encoding ascii "$bin\cx.cmd" "@echo off`r`ncodex --no-daemon --dangerously-bypass-approvals-and-sandbox %*"
  'cx is ready: it starts Codex without approvals or sandbox (plain codex stops at its background server on Windows)'
}

& {
  foreach ($id in 'Git.Git', 'Microsoft.VisualStudioCode', 'OpenJS.NodeJS.LTS') { winget install --id $id -e --source winget }
}

& {
  Start-Process ms-settings:windowsupdate-action
  winget upgrade --all
}
